l.dept_id IS NOT NULL
AND 
AND l.dept_id = #{q.deptId}
AND l.creator_id = #{q.teacherId}
AND l.lesson_id = #{q.lessonId}

    AND (l.lesson_title LIKE CONCAT('%', #{q.keyword}, '%')
         OR l.create_by LIKE CONCAT('%', #{q.keyword}, '%')
         OR EXISTS (
             SELECT 1 FROM sys_user keyword_teacher
             WHERE keyword_teacher.user_id = l.creator_id
               AND (keyword_teacher.user_name LIKE CONCAT('%', #{q.keyword}, '%')
                    OR keyword_teacher.nick_name LIKE CONCAT('%', #{q.keyword}, '%'))
         ))


    AND l.lesson_mode = #{q.lessonMode}


    AND l.entry_year = #{q.entryYear}


    AND CAST(l.grade AS CHAR) = #{q.grade}


    AND EXISTS (
        SELECT 1
        FROM biz_lesson_class_scope class_filter_scope
        WHERE class_filter_scope.lesson_id = l.lesson_id
          AND class_filter_scope.dept_id = l.dept_id
          AND class_filter_scope.class_code = #{q.classCode}
    )


    AND EXISTS (
        SELECT 1 FROM biz_lesson_question flq
        INNER JOIN biz_question fq ON fq.question_id = flq.question_id
        WHERE flq.lesson_id = l.lesson_id AND fq.question_type = 'practical'
    )


    AND NOT EXISTS (
        SELECT 1 FROM biz_lesson_question flq
        INNER JOIN biz_question fq ON fq.question_id = flq.question_id
        WHERE flq.lesson_id = l.lesson_id AND fq.question_type = 'practical'
    )

period_activity AS ( SELECT answer.lesson_id, answer.student_id, answer.submit_time AS activity_time FROM biz_student_answer answer WHERE answer.submit_time >= #{q.activityStartTime} AND answer.submit_time < #{q.activityEndTime} UNION ALL SELECT checkin.lesson_id, checkin.student_id, checkin.checkin_time FROM biz_lesson_checkin checkin WHERE checkin.checkin_time >= #{q.activityStartTime} AND checkin.checkin_time < #{q.activityEndTime} UNION ALL SELECT performance.lesson_id, performance.student_id, performance.create_time FROM biz_classroom_performance performance WHERE performance.create_time >= #{q.activityStartTime} AND performance.create_time < #{q.activityEndTime} ), period_activity_lesson AS ( SELECT DISTINCT lesson_id FROM period_activity ), base_filtered_lesson AS ( SELECT l.* FROM biz_lesson l WHERE ), practical_lesson AS ( SELECT DISTINCT lesson_question.lesson_id FROM biz_lesson_question lesson_question INNER JOIN biz_question question ON question.question_id = lesson_question.question_id AND question.question_type = 'practical' INNER JOIN base_filtered_lesson lesson ON lesson.lesson_id = lesson_question.lesson_id ), practical_class_metric AS ( SELECT answer.lesson_id, user.dept_id, student.entry_year, student.class_code, COUNT(*) AS due_count, SUM(answer.score IS NOT NULL) AS graded_count FROM biz_student_answer answer INNER JOIN base_filtered_lesson lesson ON lesson.lesson_id = answer.lesson_id INNER JOIN biz_question question ON question.question_id = answer.question_id AND question.question_type = 'practical' INNER JOIN biz_student student ON student.student_id = answer.student_id INNER JOIN sys_user user ON user.user_id = student.user_id AND user.dept_id = lesson.dept_id AND user.del_flag = '0' AND user.status = '0' WHERE answer.student_answer IS NOT NULL AND TRIM(answer.student_answer) <> '' AND answer.submit_time >= #{q.activityStartTime} AND answer.submit_time < #{q.activityEndTime} GROUP BY answer.lesson_id, user.dept_id, student.entry_year, student.class_code ), class_status AS ( SELECT scope.lesson_id, scope.dept_id, scope.entry_year, scope.class_code, CASE WHEN practical_lesson.lesson_id IS NULL THEN 'NO_PRACTICAL' WHEN deadline.deadline_id IS NULL THEN 'NOT_TRIGGERED' WHEN deadline.current_deadline_time <= NOW() THEN 'OVERDUE' WHEN deadline.last_adjustment_type = 'REOPEN' THEN 'REOPENED' WHEN IFNULL(practical_class_metric.due_count, 0) > 0 AND practical_class_metric.due_count = practical_class_metric.graded_count THEN 'COMPLETED' WHEN deadline.current_deadline_time <= DATE_ADD(NOW(), INTERVAL 72 HOUR) THEN 'DUE_SOON' ELSE 'GRADING' END AS status_code FROM biz_lesson_class_scope scope INNER JOIN base_filtered_lesson lesson ON lesson.lesson_id = scope.lesson_id LEFT JOIN practical_lesson ON practical_lesson.lesson_id = scope.lesson_id LEFT JOIN biz_practical_grading_deadline deadline ON deadline.lesson_id = scope.lesson_id AND deadline.dept_id = scope.dept_id AND deadline.entry_year = scope.entry_year AND deadline.class_code = scope.class_code LEFT JOIN practical_class_metric ON practical_class_metric.lesson_id = scope.lesson_id AND practical_class_metric.dept_id = scope.dept_id AND practical_class_metric.entry_year = scope.entry_year AND practical_class_metric.class_code = scope.class_code ), filtered_lesson AS ( SELECT lesson.* FROM base_filtered_lesson lesson
WHERE EXISTS ( SELECT 1 FROM class_status status WHERE status.lesson_id = lesson.lesson_id AND status.status_code = #{q.statusCode} )
), class_usage_metric AS ( SELECT activity.lesson_id, user.dept_id, student.entry_year, student.class_code, MIN(activity.activity_time) AS usage_date, COUNT(DISTINCT activity.student_id) AS participant_count FROM period_activity activity INNER JOIN filtered_lesson lesson ON lesson.lesson_id = activity.lesson_id INNER JOIN biz_student student ON student.student_id = activity.student_id INNER JOIN sys_user user ON user.user_id = student.user_id AND user.dept_id = lesson.dept_id AND user.status = '0' AND user.del_flag = '0' GROUP BY activity.lesson_id, user.dept_id, student.entry_year, student.class_code )

mapper.select:
WITH SELECT scope.scope_id AS scopeId, scope.lesson_id AS lessonId, scope.dept_id AS deptId, scope.entry_year AS entryYear, scope.class_code AS classCode, scope.current_assigned AS currentAssigned, class_usage.usage_date AS usageDate, COUNT(DISTINCT CASE WHEN student_user.user_id IS NOT NULL THEN student.student_id END) AS totalStudentCount, COUNT(DISTINCT CASE WHEN student_user.user_id IS NOT NULL THEN participant.student_id END) AS participantCount, COUNT(DISTINCT CASE WHEN student_user.user_id IS NOT NULL THEN practical.answer_id END) AS practicalDueCount, COUNT(DISTINCT CASE WHEN student_user.user_id IS NOT NULL AND practical.score IS NOT NULL THEN practical.answer_id END) AS practicalGradedCount, COUNT(DISTINCT CASE WHEN student_user.user_id IS NOT NULL THEN practical.answer_id END) - COUNT(DISTINCT CASE WHEN student_user.user_id IS NOT NULL AND practical.score IS NOT NULL THEN practical.answer_id END) AS practicalUngradedCount, deadline.deadline_id AS deadlineId, deadline.trigger_time AS triggerTime, deadline.current_deadline_time AS currentDeadlineTime, deadline.last_adjustment_type AS lastAdjustmentType, class_state.status_code AS statusCode FROM biz_lesson_class_scope scope INNER JOIN filtered_lesson l ON l.lesson_id = scope.lesson_id INNER JOIN class_status class_state ON class_state.lesson_id = scope.lesson_id AND class_state.dept_id = scope.dept_id AND class_state.entry_year = scope.entry_year AND class_state.class_code = scope.class_code LEFT JOIN biz_student student ON student.entry_year = scope.entry_year AND student.class_code = scope.class_code LEFT JOIN sys_user student_user ON student_user.user_id = student.user_id AND student_user.dept_id = scope.dept_id AND student_user.del_flag = '0' AND student_user.status = '0' LEFT JOIN ( SELECT DISTINCT lesson_id, student_id FROM period_activity ) participant ON participant.lesson_id = scope.lesson_id AND participant.student_id = student.student_id LEFT JOIN class_usage_metric class_usage ON class_usage.lesson_id = scope.lesson_id AND class_usage.dept_id = scope.dept_id AND class_usage.entry_year = scope.entry_year AND class_usage.class_code = scope.class_code LEFT JOIN biz_student_answer practical ON practical.lesson_id = scope.lesson_id AND practical.student_id = student.student_id AND practical.student_answer IS NOT NULL AND TRIM(practical.student_answer) <> '' AND practical.submit_time >= #{q.activityStartTime} AND practical.submit_time < #{q.activityEndTime} AND EXISTS (SELECT 1 FROM biz_question pq WHERE pq.question_id = practical.question_id AND pq.question_type = 'practical') LEFT JOIN biz_practical_grading_deadline deadline ON deadline.lesson_id = scope.lesson_id AND deadline.dept_id = scope.dept_id AND deadline.entry_year = scope.entry_year AND deadline.class_code = scope.class_code WHERE 1 = 1
AND scope.class_code = #{q.classCode}
AND class_state.status_code = #{q.statusCode}
GROUP BY scope.scope_id, scope.lesson_id, scope.dept_id, scope.entry_year, scope.class_code, scope.current_assigned, class_usage.usage_date, deadline.deadline_id, deadline.trigger_time, deadline.current_deadline_time, deadline.last_adjustment_type, class_state.status_code ORDER BY scope.entry_year DESC, CAST(scope.class_code AS UNSIGNED), scope.class_code

SELECT student.student_id AS studentId, user.nick_name AS studentName, student.student_no AS studentNo, student.entry_year AS entryYear, student.class_code AS classCode, EXISTS(SELECT 1 FROM biz_student_answer answer WHERE answer.lesson_id = #{q.lessonId} AND answer.student_id = student.student_id) AS submitted, IFNULL((SELECT SUM(IFNULL(answer.score, 0)) FROM biz_student_answer answer WHERE answer.lesson_id = #{q.lessonId} AND answer.student_id = student.student_id), 0) AS originalHomeworkScore, COALESCE( (SELECT CASE WHEN adjustment.action_type = 'UPDATE' THEN adjustment.adjusted_homework_score ELSE NULL END FROM biz_score_adjustment adjustment WHERE adjustment.lesson_id = #{q.lessonId} AND adjustment.student_id = student.student_id ORDER BY adjustment.adjustment_id DESC LIMIT 1), IFNULL((SELECT SUM(IFNULL(answer.score, 0)) FROM biz_student_answer answer WHERE answer.lesson_id = #{q.lessonId} AND answer.student_id = student.student_id), 0) ) AS homeworkScore, IFNULL(performance.score, 0) AS performanceScore, performance.is_absent AS absent, CASE WHEN performance.is_absent = 1 THEN NULL ELSE LEAST(100, GREATEST(0, COALESCE( (SELECT CASE WHEN adjustment.action_type = 'UPDATE' THEN adjustment.adjusted_homework_score ELSE NULL END FROM biz_score_adjustment adjustment WHERE adjustment.lesson_id = #{q.lessonId} AND adjustment.student_id = student.student_id ORDER BY adjustment.adjustment_id DESC LIMIT 1), IFNULL((SELECT SUM(IFNULL(answer.score, 0)) FROM biz_student_answer answer WHERE answer.lesson_id = #{q.lessonId} AND answer.student_id = student.student_id), 0) ) + IFNULL(performance.score, 0))) END AS finalScore, COUNT(DISTINCT practical.answer_id) AS practicalDueCount, COUNT(DISTINCT CASE WHEN practical.score IS NOT NULL THEN practical.answer_id END) AS practicalGradedCount, COUNT(DISTINCT practical.answer_id) - COUNT(DISTINCT CASE WHEN practical.score IS NOT NULL THEN practical.answer_id END) AS practicalUngradedCount, CASE WHEN COUNT(DISTINCT practical.answer_id) = 0 THEN 'NOT_SUBMITTED' WHEN COUNT(DISTINCT practical.answer_id) = COUNT(DISTINCT CASE WHEN practical.score IS NOT NULL THEN practical.answer_id END) THEN 'GRADED' ELSE 'UNGRADED' END AS practicalStatus FROM biz_student student INNER JOIN sys_user user ON user.user_id = student.user_id AND user.dept_id = #{q.deptId} AND user.del_flag = '0' AND user.status = '0' LEFT JOIN biz_classroom_performance performance ON performance.student_id = student.student_id AND performance.lesson_id = #{q.lessonId} LEFT JOIN biz_student_answer practical ON practical.student_id = student.student_id AND practical.lesson_id = #{q.lessonId} AND practical.student_answer IS NOT NULL AND TRIM(practical.student_answer) <> '' AND EXISTS (SELECT 1 FROM biz_question pq WHERE pq.question_id = practical.question_id AND pq.question_type = 'practical') WHERE student.entry_year = #{q.entryYear} AND student.class_code = #{q.classCode}
AND (user.nick_name LIKE CONCAT('%', #{q.keyword}, '%') OR student.student_no LIKE CONCAT('%', #{q.keyword}, '%'))
GROUP BY student.student_id, user.nick_name, student.student_no, student.entry_year, student.class_code, performance.score, performance.is_absent ORDER BY CAST(student.student_no AS UNSIGNED), student.student_no
